// Package syscalls maps syscall numbers to names for the architecture the
// binary is built for. The tables are generated by tools/gensyscalls.
package syscalls

import "strconv"

// Name returns the syscall name, or "sys_<nr>" if the number is unknown.
func Name(nr uint32) string {
	if n, ok := names[int(nr)]; ok {
		return n
	}
	return "sys_" + strconv.Itoa(int(nr))
}

// Number returns the syscall number for a name.
func Number(name string) (uint32, bool) {
	for nr, n := range names {
		if n == name {
			return uint32(nr), true
		}
	}
	return 0, false
}

// blocking syscalls spend most of their time waiting for something else, so
// a long latency is expected and says little about slowness.
var blocking = map[string]bool{
	"epoll_wait": true, "epoll_pwait": true, "epoll_pwait2": true,
	"poll": true, "ppoll": true, "select": true, "pselect6": true,
	"nanosleep": true, "clock_nanosleep": true, "futex": true,
	"wait4": true, "waitid": true, "pause": true, "rt_sigtimedwait": true,
	"accept": true, "accept4": true, "io_getevents": true,
	"sigsuspend": true, "rt_sigsuspend": true, "msgrcv": true,
	"semop": true, "semtimedop": true,
}

// IsBlocking reports whether the syscall is expected to wait.
func IsBlocking(name string) bool { return blocking[name] }
